begin;

-- Preserve pedagogical labels after a reschedule and include future rescheduled meetings.
create or replace function logos_academy.admin_dashboard(p_tenant_id uuid,p_actor_user_id uuid,p_encryption_key text,p_class_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v jsonb;
begin
 perform private.assert_tenant_admin(p_tenant_id,p_actor_user_id); if length(coalesce(p_encryption_key,''))=0 then raise exception using errcode='22023',message='encryption key required'; end if;
 if p_class_id is not null and not exists(select 1 from logos_academy.classes c where c.tenant_id=p_tenant_id and c.id=p_class_id and c.deleted_at is null) then raise exception using errcode='42501',message='class unavailable'; end if;
 with ordered_lessons as (
   select lt.*,row_number() over(partition by c.curriculum_id order by c.position,lt.position,lt.id)::integer global_position
   from logos_academy.lesson_templates lt
   join logos_academy.cycles c on c.tenant_id=lt.tenant_id and c.id=lt.cycle_id and c.deleted_at is null
   where lt.tenant_id=p_tenant_id and lt.deleted_at is null
 ), scope as (select e.id,e.student_profile_id,e.status from logos_academy.enrollments e where e.tenant_id=p_tenant_id and e.deleted_at is null and (p_class_id is null or e.class_id=p_class_id)), pending as (select aa.enrollment_id,count(*) filter(where aa.due_at<now() and aa.status in ('available','draft','revision_requested'))::int n from logos_academy.activity_assignments aa join scope s on s.id=aa.enrollment_id where aa.tenant_id=p_tenant_id and aa.deleted_at is null group by aa.enrollment_id), makeups as (select ar.enrollment_id,count(*)::int n from logos_academy.attendance_records ar join scope s on s.id=ar.enrollment_id where ar.tenant_id=p_tenant_id and ar.status='absent' and ar.deleted_at is null and not exists(select 1 from logos_academy.makeup_records mr where mr.tenant_id=ar.tenant_id and mr.attendance_record_id=ar.id and mr.deleted_at is null and mr.completed_at<=now()) group by ar.enrollment_id), rates as (select count(*) filter(where r.decision='approved')::numeric approved,count(*)::numeric total from logos_academy.reviews r join logos_academy.submissions su on su.tenant_id=r.tenant_id and su.id=r.submission_id join logos_academy.activity_assignments aa on aa.tenant_id=su.tenant_id and aa.id=su.activity_assignment_id join scope s on s.id=aa.enrollment_id where r.tenant_id=p_tenant_id and r.deleted_at is null and su.deleted_at is null)
 select jsonb_build_object('awaitingReviewCount',(select count(*) from logos_academy.activity_assignments aa join scope s on s.id=aa.enrollment_id where aa.tenant_id=p_tenant_id and aa.status='submitted' and aa.deleted_at is null),'feedbackDueSoonCount',(select count(*) from logos_academy.submissions su join logos_academy.activity_assignments aa on aa.tenant_id=su.tenant_id and aa.id=su.activity_assignment_id join scope s on s.id=aa.enrollment_id where su.tenant_id=p_tenant_id and not su.is_draft and aa.status='submitted' and su.submitted_at<=now()-interval '46 hours' and su.deleted_at is null),'overdueAssignmentCount',coalesce((select sum(n) from pending),0),'pendingMakeupCount',coalesce((select sum(n) from makeups),0),'deliveryApprovalRate',case when rates.total=0 then 0 else round(rates.approved/rates.total*100,2) end,'upcomingSessions',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'lessonPosition',lt.global_position,'lessonTitle',lt.title,'startsAt',s.starts_at,'endsAt',s.ends_at,'status',s.status) order by s.starts_at,s.id) from (select * from logos_academy.sessions s where s.tenant_id=p_tenant_id and s.deleted_at is null and s.status in ('scheduled','rescheduled') and s.starts_at>=now() and (p_class_id is null or s.class_id=p_class_id) order by s.starts_at,s.id limit 5) s join ordered_lessons lt on lt.tenant_id=s.tenant_id and lt.id=s.lesson_template_id),'[]'::jsonb),'studentsAtRisk',coalesce((select jsonb_agg(jsonb_build_object('id',sp.id,'displayName',u.display_name,'email',extensions.pgp_sym_decrypt(u.email_encrypted,p_encryption_key),'githubUsername',sp.github_username,'activeEnrollmentCount',case when s.status='active' then 1 else 0 end,'pendingAssignmentCount',coalesce(p.n,0),'pendingMakeupCount',coalesce(m.n,0)) order by u.display_name) from scope s join logos_academy.student_profiles sp on sp.tenant_id=p_tenant_id and sp.id=s.student_profile_id join logos_academy.users u on u.tenant_id=sp.tenant_id and u.id=sp.user_id left join pending p on p.enrollment_id=s.id left join makeups m on m.enrollment_id=s.id where coalesce(p.n,0)>0 or coalesce(m.n,0)>0),'[]'::jsonb)) into v from rates;
 return v;
end;
$$;

revoke all on function logos_academy.admin_dashboard(uuid,uuid,text,uuid) from public,anon,authenticated;
grant execute on function logos_academy.admin_dashboard(uuid,uuid,text,uuid) to service_role;
notify pgrst,'reload schema';
commit;
